{"is_source_file": true, "format": "SQL", "description": "This file contains SQL statements to configure Row Level Security (RLS) policies on the 'profiles' table in a PostgreSQL database, including enabling RLS, removing existing policies, creating a new policy for user-specific insert/update operations, and guidance for verification and troubleshooting.", "external_files": ["assets/supabase.md"], "external_methods": [], "published": [], "classes": [], "methods": [], "calls": ["ALTER TABLE profiles ENABLE ROW LEVEL SECURITY", "DROP POLICY IF EXISTS \"Users can insert or update their own profile\" ON profiles", "CREATE POLICY \"Users can insert or update their own profile\" ON profiles FOR INSERT, UPDATE USING (auth.uid() = id) WITH CHECK (auth.uid() = id)", "SELECT * FROM pg_policies WHERE tablename = 'profiles'", "insert into profiles (id, email, role) values (auth.uid(), 'test@example.com', 'citizen') ON CONFLICT (id) DO UPDATE SET email=excluded.email, role=excluded.role"], "search-terms": ["Row Level Security", "policies on profiles table", "auth.uid()", "CREATE POLICY", "pg_policies", "supabase"], "state": 2, "file_id": 83, "knowledge_revision": 226, "git_revision": "72e3b37302f78b26353c0dd8383d63c0ec416aee", "hash": "c980012d9ec736c67b34e800b74703b2", "format-version": 4, "code-base-name": "default", "filename": "citizen_authority_frontend_workspace/assets/supabase_applied_rls.sql", "revision_history": [{"226": "72e3b37302f78b26353c0dd8383d63c0ec416aee"}]}